import json, os
import numpy as np
from pathlib import Path
from sklearn.metrics import roc_curve, roc_auc_score

BASE_DIR = Path("/root/autodl-tmp/collapse_severity_monitor")
SEEDS = [42, 43, 44]
FRACS = [0, 50]
GENS = list(range(5))
SIGNALS = ['stable_rank', 'training_loss', 'spectral_entropy', 'perplexity']
MAX_STEP = 1600

def load_signals(seed, frac, gen):
    path = BASE_DIR / f"outputs_qwen15b_seed{seed}_wikitext" / f"signals_{frac}pct_gen{gen}.jsonl"
    if not path.exists():
        return []
    records = []
    with open(path) as f:
        for line in f:
            r = json.loads(line.strip())
            if r.get('step', -1) < 0 or 'spectral_entropy' not in r:
                continue
            records.append(r)
    return records

data = {}
for seed in SEEDS:
    for frac in FRACS:
        for gen in GENS:
            recs = load_signals(seed, frac, gen)
            if recs:
                data[(seed, frac, gen)] = recs

print(f"Loaded {len(data)} signal files")

baselines = {}
for seed in SEEDS:
    baselines[seed] = {}
    gen0 = data.get((seed, 0, 0), [])
    if not gen0:
        raise ValueError(f"Missing gen0 frac=0% for seed {seed}")
    for sig in SIGNALS:
        baselines[seed][sig] = np.mean([r[sig] for r in gen0])

def compute_features(records, seed, signal):
    bl = baselines[seed][signal]
    return np.array([abs(r[signal] - bl) / abs(bl) for r in records])

def build_pooled_dataset(signal, max_progress=1.0, gen_range=range(1, 5)):
    X, y = [], []
    for gen in gen_range:
        for seed in SEEDS:
            for frac in FRACS:
                key = (seed, frac, gen)
                if key not in data:
                    continue
                recs = [r for r in data[key] if r['step'] / MAX_STEP <= max_progress]
                if not recs:
                    continue
                feats = compute_features(recs, seed, signal)
                X.extend(feats)
                y.extend([1 if frac == 50 else 0] * len(feats))
    return np.array(X), np.array(y)

result = {}
for sig in SIGNALS:
    X, y = build_pooled_dataset(sig, max_progress=1.0)
    if len(np.unique(y)) < 2:
        print(f"  {sig}: skipped (only one class)")
        continue
    fpr, tpr, thresholds = roc_curve(y, X)
    auc = roc_auc_score(y, X)
    result[sig] = {
        'fpr': fpr.tolist(),
        'tpr': tpr.tolist(),
        'auc': float(auc),
        'n_samples': len(X),
        'n_pos': int(y.sum()),
        'n_neg': int(len(y) - y.sum()),
    }
    print(f"  {sig}: AUC={auc:.4f}, n={len(X)}, fpr_points={len(fpr)}")

# Also compute per-progress ROC for panel (b) verification
progress_thresholds = [0.10, 0.20, 0.50, 1.0]
progress_auc = {}
for sig in SIGNALS:
    progress_auc[sig] = []
    for prog in progress_thresholds:
        X, y = build_pooled_dataset(sig, max_progress=prog)
        if len(np.unique(y)) < 2:
            progress_auc[sig].append(0.5)
            continue
        auc = roc_auc_score(y, X)
        progress_auc[sig].append(float(auc))
    print(f"  {sig} progress AUC: {progress_auc[sig]}")

output = {
    'roc_curves': result,
    'progress_auc': progress_auc,
    'progress_thresholds': [int(p*100) for p in progress_thresholds],
}

out_path = BASE_DIR / "artifacts" / "early_warning_roc" / "roc_curves_data.json"
with open(out_path, 'w') as f:
    json.dump(output, f, indent=2)
print(f"\nSaved to {out_path}")
